const shows=[{title:'Morning Dew',desc:'Soft sounds for a slow start and a second cup.',tracks:['First Light — June Meadow','Open Window — Soft Air','The Long Way Home — Mira']},{title:'The Garden Party',desc:'A sun-soaked patch of soul, rhythm and good company.',tracks:['Orange Blossom — The Petals','Backyard Boogie — Jude','Golden Hour — The Seeds']},{title:'Wild Frequency',desc:'A little left of center, and all the more beautiful for it.',tracks:['Electric Moss — Sol','Strange Fruit Garden — Hush','Other Side of Green — Echo']},{title:'After Bloom',desc:'Tender sounds for the hours when the sky turns violet.',tracks:['Violet Hour — Noor','Moonflower — Still Life','Night Swimming — Vale']}];let current=0;function selectShow(i){current=i;const s=shows[i];document.querySelector('#show-title').textContent=s.title;document.querySelector('#show-desc').textContent=s.desc;document.querySelector('#needle').style.left=[5,35,65,95][i]+'%';document.querySelector('#tracklist').innerHTML=s.tracks.map((track,n)=>`<button type="button" data-track="${n}" aria-pressed="${n===0}">${n===0?'✳':'○'} ${track}</button>`).join('');document.querySelectorAll('.dial-buttons [data-show]').forEach(el=>el.setAttribute('aria-pressed',String(+el.dataset.show===i)));document.querySelectorAll('.schedule-row').forEach(el=>el.classList.toggle('active',+el.dataset.show===i))}document.addEventListener('click',e=>{const show=e.target.closest('[data-show]');if(show){selectShow(+show.dataset.show);if(show.classList.contains('schedule-row'))document.querySelector('#dial').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return}const track=e.target.closest('[data-track]');if(track){document.querySelectorAll('[data-track]').forEach(el=>{const active=el===track;el.setAttribute('aria-pressed',String(active));el.classList.toggle('selected',active);el.textContent=(active?'✳':'○')+' '+shows[current].tracks[+el.dataset.track]})}});document.querySelector('#signup').addEventListener('submit',e=>{e.preventDefault();document.querySelector('#form-message').textContent='Thanks for visiting! This is a demo; no email was sent or stored.'});selectShow(0);
